xql_query:
// ============================================================
// Rule: THM_PureRAT C2 Activity via AddInProcess32
// Vendor: Windows
// Objective:
// Detect activity associated with THM_PureRAT C2 Activity via AddInProcess32.
// Severity: SEV_040_HIGH
// Category: EXECUTION
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0011 - Command and Control
// Technique: T1071.001 - Application Layer Protocol: Web Protocols

// Configuração inicial: define que as comparações não diferenciam maiúsculas/minúsculas  
config case_sensitive = false  

// Fonte de dados: dataset de telemetria de endpoint do Cortex XDR  
// O dataset 'xdr_data' contém eventos brutos coletados pelos agentes instalados  
// em endpoints (Windows, Linux, macOS), abrangendo processos, conexões de rede,  
// acessos a arquivos e alterações de registro  
| dataset = xdr_data  

// Filtro para restringir os eventos ao tipo "STORY"  
// O tipo ENUM.STORY representa eventos consolidados e enriquecidos  
// que descrevem narrativas de execução de processos e cadeias de causalidade  
| filter event_type = ENUM.STORY  

// Filtro para identificar processos específicos que participam da narrativa  
// O processo 'AddInProcess32.exe' está associado a componentes .NET e COM+  
// e pode ser abusado para execução de código em contexto de aplicativos legítimos  
| filter actor_process_image_name = "AddInProcess32.exe"  

// Filtro para restringir eventos que envolvem conexões de rede na porta 56001  
// Essa porta é incomum em comunicações padrão e pode indicar beaconing, C2,  
// ou comunicação interna entre componentes comprometidos  
| filter action_remote_port = 56001  

// Seleção dos campos relevantes para análise e correlação forense  
// Inclui informações sobre o host, usuário, IP remoto, porta e cadeia de execução  
| fields agent_hostname,                        // Nome do endpoint que originou o evento  
         actor_effective_username,               // Usuário efetivo sob o qual o processo foi executado  
         action_remote_ip,                       // Endereço IP remoto de destino  
         action_remote_port,                     // Porta remota associada à conexão  
         dst_action_external_hostname,           // Nome do host externo, se resolvido  
         actor_process_image_name,               // Nome do processo executado  
         actor_process_image_path,               // Caminho completo do executável  
         actor_process_command_line,             // Linha de comando utilizada na execução  
         causality_actor_process_image_name,     // Processo pai (origem causal)  
         causality_actor_process_image_path,     // Caminho do processo pai  
         causality_actor_process_command_line    // Linha de comando do processo pai
